import{_ as a,o as e,c as i,a3 as l}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"30분 퀵스타트","description":"제로에서 MiniTavern이 로컬 모델 첫 응답을 받을 때까지 — Ollama 또는 LM Studio, 모델, LAN, App 연결, 약 30분.","frontmatter":{"title":"30분 퀵스타트","description":"제로에서 MiniTavern이 로컬 모델 첫 응답을 받을 때까지 — Ollama 또는 LM Studio, 모델, LAN, App 연결, 약 30분.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"30분 퀵스타트 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"제로에서 MiniTavern이 로컬 모델 첫 응답을 받을 때까지 — Ollama 또는 LM Studio, 모델, LAN, App 연결, 약 30분."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/quickstart"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/quickstart"}]]},"headers":[],"relativePath":"ko/quickstart.md","filePath":"ko/quickstart.md","lastUpdated":1787224147000}'),o={name:"ko/quickstart.md"};function r(s,t,n,d,p,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_30분-퀵스타트" tabindex="-1">30분 퀵스타트 <a class="header-anchor" href="#_30분-퀵스타트" aria-label="Permalink to &quot;30분 퀵스타트&quot;">​</a></h1><p>목표: 제로에서 MiniTavern이 로컬 모델의 첫 응답을 받기까지.</p><table tabindex="0"><thead><tr><th>단계</th><th>대략 시간</th><th>할 일</th></tr></thead><tbody><tr><td>1</td><td>0–5분</td><td>도구 선택: Ollama 또는 LM Studio</td></tr><tr><td>2</td><td>5–15분</td><td>설치하고 작은 모델 다운로드</td></tr><tr><td>3</td><td>15–20분</td><td>LAN / Local Server 활성화</td></tr><tr><td>4</td><td>20–25분</td><td>PC LAN IP 확인</td></tr><tr><td>5</td><td>25–30분</td><td>MiniTavern에서 연결 만들고 테스트</td></tr></tbody></table><hr><h2 id="step-1-도구-선택" tabindex="-1">Step 1: 도구 선택 <a class="header-anchor" href="#step-1-도구-선택" aria-label="Permalink to &quot;Step 1: 도구 선택&quot;">​</a></h2><ul><li><strong>가장 빨리</strong>: <a href="./ollama/install">Ollama</a> 또는 <a href="./lmstudio/install">LM Studio</a></li><li><strong>롤플레이 지향</strong>: 이후 <a href="./koboldcpp/install">KoboldCPP</a></li><li><strong>이미 GGUF</strong>: <a href="./llamacpp/install">llama.cpp</a></li></ul><p>전체 비교: <a href="./local/tools">도구 개요</a>. 아래는 <strong>Ollama</strong> 기준 통관; 다른 도구는 「모델 받기 / 서비스」만 해당 장으로 바꾸면 Step 5는 동일.</p><hr><h2 id="step-2-설치와-작은-모델" tabindex="-1">Step 2: 설치와 작은 모델 <a class="header-anchor" href="#step-2-설치와-작은-모델" aria-label="Permalink to &quot;Step 2: 설치와 작은 모델&quot;">​</a></h2><ol><li><a href="./ollama/install">Ollama 설치</a>.</li><li>터미널（검증용 작은 모델）:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><ol start="3"><li>로컬 확인:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><p>대화 후 <code>/bye</code>로 종료. 더 많은 모델: <a href="./ollama/models">다운로드와 선택</a>.</p><hr><h2 id="step-3-lan-접근" tabindex="-1">Step 3: LAN 접근 <a class="header-anchor" href="#step-3-lan-접근" aria-label="Permalink to &quot;Step 3: LAN 접근&quot;">​</a></h2><p><a href="./ollama/lan">LAN 접근 활성화</a>에서 <code>OLLAMA_HOST=0.0.0.0</code>, 방화벽 <strong>11434</strong>.</p><p>완료 후 <strong>PC 로컬</strong> 브라우저（응답만 있으면 됨, 예쁜 페이지 불필요）:</p><p><code>http://127.0.0.1:11434</code></p><hr><h2 id="step-4-pc-lan-ip" tabindex="-1">Step 4: PC LAN IP <a class="header-anchor" href="#step-4-pc-lan-ip" aria-label="Permalink to &quot;Step 4: PC LAN IP&quot;">​</a></h2><ul><li><strong>Windows</strong>: <code>Win + R</code> → <code>cmd</code> → <code>ipconfig</code>, 「무선 LAN 어댑터」<strong>IPv4</strong>（예 <code>192.168.x.x</code>）.</li><li><strong>macOS</strong>: 시스템 설정 → 네트워크 → 현재 Wi‑Fi → 상세 IP; 또는 <code>ipconfig getifaddr en0</code>.</li></ul><p>이 IP를 <code>YOUR_PC_IP</code>로 기록.</p><hr><h2 id="step-5-minitavern-설정" tabindex="-1">Step 5: MiniTavern 설정 <a class="header-anchor" href="#step-5-minitavern-설정" aria-label="Permalink to &quot;Step 5: MiniTavern 설정&quot;">​</a></h2><ol><li>App → <strong>설정 → 모델 → 모델 연결 → 새로 만들기</strong>.</li><li>플랫폼 <strong>Custom / OpenAI 호환</strong>（App 실제 옵션명）.</li><li>입력:</li></ol><table tabindex="0"><thead><tr><th>필드</th><th>예（Ollama）</th></tr></thead><tbody><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:11434/v1</code></td></tr><tr><td>API Key</td><td>비움 또는 임의 자리（로컬은 보통 미검증）</td></tr><tr><td>모델명</td><td><code>llama3.2:3b</code>（<code>ollama list</code>와 일치）</td></tr></tbody></table><ol start="4"><li>저장·<strong>테스트</strong>; 성공 후 기본값, 캐릭터 가져와 채팅.</li></ol><p>UI 전체: <a href="./connect-app/minitavern">MiniTavern 설정</a>.</p><hr><h2 id="실패했다면" tabindex="-1">실패했다면? <a class="header-anchor" href="#실패했다면" aria-label="Permalink to &quot;실패했다면?&quot;">​</a></h2><ul><li>테스트 실패, 타임아웃, 빈 응답 → <a href="./troubleshoot">문제 해결 표</a></li><li>가장 흔함: <strong>Base URL에 <code>localhost</code></strong>, 또는 폰·PC가 다른 Wi‑Fi</li></ul>',32)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
